create table xxcus.xxfnd_documents (
    document_id            number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment
    by 1 cache 20 noorder nocycle nokeep noscale not null enable,
    category_code          varchar2(30 byte) not null enable,
    datatype_code          varchar2(30 byte) not null enable,
    base_document_id       number,
    version_number         number default 1 not null enable,
    storage_config_id      number,
    storage_type           varchar2(30 byte),
    external_document_id   varchar2(500 byte),
    external_version_id    varchar2(500 byte),
    external_url           varchar2(2000 byte),
    file_name              varchar2(400 byte),
    mime_type              varchar2(255 byte),
    file_size_bytes        number,
    text_content           clob,
    url                    varchar2(2000 byte),
    document_date          date,
    expiry_date            date,
    upload_status          varchar2(20 byte) default 'PENDING' not null enable,
    upload_error           varchar2(4000 byte),
    automated_check_status varchar2(30 byte) default 'NOT_CHECKED' not null enable,
    start_date_active      date default trunc(sysdate) not null enable,
    end_date_active        date,
    created_by             varchar2(255 byte) not null enable,
    creation_date          timestamp(6) not null enable,
    last_updated_by        varchar2(255 byte) not null enable,
    last_update_date       timestamp(6) not null enable,
    last_update_login      varchar2(255 byte),
    object_version_number  number default 1 not null enable
);

alter table xxcus.xxfnd_documents
    add constraint xxfnd_documents_ck1
        check ( datatype_code in ( 'FILE', 'SHORT_TEXT', 'LONG_TEXT', 'WEB_PAGE' ) ) enable;

alter table xxcus.xxfnd_documents
    add constraint xxfnd_documents_ck2
        check ( upload_status in ( 'PENDING', 'STORED', 'FAILED', 'NOT_APPLICABLE' ) ) enable;

alter table xxcus.xxfnd_documents
    add constraint xxfnd_documents_ck3
        check ( automated_check_status in ( 'NOT_CHECKED', 'PASSED', 'FLAGGED' ) ) enable;

alter table xxcus.xxfnd_documents
    add constraint xxfnd_documents_ck4
        check ( ( datatype_code = 'FILE'
                  and storage_type in ( 'UCM', 'SHAREPOINT' )
                  and file_name is not null )
                or ( datatype_code = 'WEB_PAGE'
                     and url is not null
                     and storage_type is null )
                or ( datatype_code in ( 'SHORT_TEXT', 'LONG_TEXT' )
                     and storage_type is null ) ) enable;

alter table xxcus.xxfnd_documents
    add constraint xxfnd_documents_pk primary key ( document_id )
        using index enable;


